Tool response:
Tool: search_board_posts
Description: Search posts in a specific board with filters and sorting.

Specifically for the task:
- Board: 'Product Feedback' (ID 1 based on snapshot, but we use path param)
- Keyword: 'dark mode'
- Status: 'Under Review'
- Category: 'UI/UX'
- Tag: 'mobile'
- Sort: votes descending
- Limit: top 5
Parameters:
    {
      "type": "object",
      "properties": {
        "board_id": {
          "type": "integer",
          "title": "Board Id",
          "description": ""
        },
        "keyword": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Keyword to search in post titles",
          "title": "Keyword"
        },
        "status": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Status name to filter by",
          "title": "Status"
        },
        "category": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Category name to filter by",
          "title": "Category"
        },
        "tag": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Tag name to filter by",
          "title": "Tag"
        },
        "limit": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum number of results to return",
          "title": "Limit"
        }
      },
      "required": [
        "board_id"
      ]
    }
